#[track_caller]
fn on_endpoint(mut self, filter: MethodFilter, endpoint: MethodEndpoint<S, B, E>) -> Self {
    // written as a separate function to generate less IR
    #[track_caller]
    fn set_endpoint<S, B, E>(
        method_name: &str,
        out: &mut MethodEndpoint<S, B, E>,
        endpoint: &MethodEndpoint<S, B, E>,
        endpoint_filter: MethodFilter,
        filter: MethodFilter,
        allow_header: &mut AllowHeader,
        methods: &[&'static str],
    ) where
        MethodEndpoint<S, B, E>: Clone,
        S: Clone,
    {
        if endpoint_filter.contains(filter) {
            if out.is_some() {
                panic!(
                    "Overlapping method route. Cannot add two method routes that both handle \
                     `{method_name}`",
                )
            }
            *out = endpoint.clone();
            for method in methods {
                append_allow_header(allow_header, method);
            }
        }
    }

    set_endpoint(
        "GET",
        &mut self.get,
        &endpoint,
        filter,
        MethodFilter::GET,
        &mut self.allow_header,
        &["GET", "HEAD"],
    );

    set_endpoint(
        "HEAD",
        &mut self.head,
        &endpoint,
        filter,
        MethodFilter::HEAD,
        &mut self.allow_header,
        &["HEAD"],
    );

    set_endpoint(
        "TRACE",
        &mut self.trace,
        &endpoint,
        filter,
        MethodFilter::TRACE,
        &mut self.allow_header,
        &["TRACE"],
    );

    set_endpoint(
        "PUT",
        &mut self.put,
        &endpoint,
        filter,
        MethodFilter::PUT,
        &mut self.allow_header,
        &["PUT"],
    );

    set_endpoint(
        "POST",
        &mut self.post,
        &endpoint,
        filter,
        MethodFilter::POST,
        &mut self.allow_header,
        &["POST"],
    );

    set_endpoint(
        "PATCH",
        &mut self.patch,
        &endpoint,
        filter,
        MethodFilter::PATCH,
        &mut self.allow_header,
